// Correct behavior, borrowed vocabulary: nothing here speaks the
// clinic's language, so every reader translates as they go.
public class DataManager
{
    private readonly List<Item> _list = new();

    // "Process" what? The reader must open the body to learn that
    // this books a patient into a slot — unless it is taken.
    public bool ProcessItem(string id1, string id2)
    {
        foreach (var obj in _list)
        {
            if (obj.Key2 == id2) return false;
        }
        _list.Add(new Item { Key1 = id1, Key2 = id2 });
        return true;
    }

    // "GetData" names a direction, not a concept: this counts the
    // slots a patient has booked today.
    public int GetData(string id1)
    {
        var temp = 0;
        foreach (var obj in _list)
        {
            if (obj.Key1 == id1) temp++;
        }
        return temp;
    }
}

// Grep test: search this file for "appointment", "patient", or
// "slot" — the domain's three central words. Zero hits.

modelExamples.after:
// The same behavior in the clinic's own words. The domain expert's
// sentence — "book the patient into the slot, unless it is taken" —
// now reads straight off the code.
public class AppointmentBook
{
    private readonly List<Appointment> _appointments = new();

    public bool Book(string patientId, string slotId)
    {
        foreach (var appointment in _appointments)
        {
            if (appointment.SlotId == slotId) return false;
        }
        _appointments.Add(new Appointment
        {
            PatientId = patientId,
            SlotId = slotId,
        });
        return true;
    }

    public int BookingsFor(string patientId)
    {
        var bookings = 0;
        foreach (var appointment in _appointments)
        {
            if (appointment.PatientId == patientId) bookings++;
        }
        return bookings;
    }
}

// The same grep now finds every place the code touches the concept.
// Not one line of behavior changed — only what the reader pays.

