// Say this class's responsibility in one sentence starting with
// its name: "OrderService prices the order AND emails the
// confirmation." The "and" is load-bearing — and so is the vague
// name that let both jobs hide under one roof.
public class OrderService
{
    private readonly ISmtpClient _smtp;

    public OrderService(ISmtpClient smtp) => _smtp = smtp;

    public decimal Complete(Order order)
    {
        // Job one: price it.
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            total += line.UnitPrice * line.Quantity;
        }
        if (total >= 100m) total *= 0.95m;

        // Job two: announce it.
        _smtp.Send(
            order.CustomerEmail,
            "Your order",
            $"Your total is {total:C}.");

        return total;
    }
}

// "Service" is the tell: a name vague enough to cover any second
// job that wanders in. Nobody can call one job without the other.

modelExamples.after:
// Two sentences, no "and" — and now the names could not absorb a
// stray second job if one tried to move in.
public class OrderPricer
{
    // "OrderPricer prices the order." One sentence, whole.
    public decimal Price(Order order)
    {
        decimal total = 0m;
        foreach (var line in order.Lines)
        {
            total += line.UnitPrice * line.Quantity;
        }
        return total >= 100m ? total * 0.95m : total;
    }
}

public class ConfirmationMailer
{
    private readonly ISmtpClient _smtp;

    public ConfirmationMailer(ISmtpClient smtp) => _smtp = smtp;

    // "ConfirmationMailer mails the confirmation." Also whole.
    public void Send(Order order, decimal total)
    {
        _smtp.Send(
            order.CustomerEmail,
            "Your order",
            $"Your total is {total:C}.");
    }
}

// The caller now composes the two by name — and can price an order
// without sending an email, which the old name quietly forbade.

