// Every name here is trusted hundreds of times — and each one
// lies about what the body does.
public class SubscriberDirectory
{
    private readonly Dictionary<string, Subscriber> _byEmail = new();

    // "Get" — but an unknown email is silently REGISTERED. Callers
    // probing "does this subscriber exist?" create it by asking.
    public Subscriber GetSubscriber(string email)
    {
        if (!_byEmail.TryGetValue(email, out var subscriber))
        {
            subscriber = new Subscriber(email);
            _byEmail[email] = subscriber;
        }
        return subscriber;
    }

    // "Is…" promises a pure question — but the check is also
    // RECORDED, so asking twice gives a different history.
    public bool IsActive(string email)
    {
        var subscriber = GetSubscriber(email);
        subscriber.ChecksRecorded++;
        return subscriber.Unsubscribed == false;
    }
}

// The prediction check fails twice: read each signature, write
// down what you expect, then read the body. Both bodies do more.

modelExamples.after:
// The same operations under honest names. Nothing about the
// behavior changed yet — but now the names confess it.
public class SubscriberDirectory
{
    private readonly Dictionary<string, Subscriber> _byEmail = new();

    // The name now carries the side effect it always had.
    public Subscriber FindOrRegisterSubscriber(string email)
    {
        if (!_byEmail.TryGetValue(email, out var subscriber))
        {
            subscriber = new Subscriber(email);
            _byEmail[email] = subscriber;
        }
        return subscriber;
    }

    // Honesty made the smell legible: a name that needs "and"
    // is the split point, found by renaming alone.
    public bool RecordCheckAndReportActive(string email)
    {
        var subscriber = FindOrRegisterSubscriber(email);
        subscriber.ChecksRecorded++;
        return subscriber.Unsubscribed == false;
    }
}

// First make the name tell the truth; the truthful name then
// tells you what to fix. A lying name hides the flaw forever.

exercises.targetInterfaceCode:
public interface ILendingDesk
{
    // Puts one copy of the title on the shelf; call once per copy.
    void AddCopy(string title);

    // Lends one shelved copy to the member. False — and nothing is
    // recorded — when no copy is on the shelf, the member already
    // holds 3 loans, or the member already holds this title.
    bool CheckOut(string memberId, string title);

    // Takes the member's copy of the title back onto the shelf.
    // False when the member holds no loan of this title.
    bool Return(string memberId, string title);

    // Copies of the title on the shelf right now. Unknown title: 0.
    int CopiesOnShelf(string title);
}

public interface IFrontDesk
{
    // Opens the room for guests; call once per room.
    void AddRoom(string roomNumber);

    // Checks the guest in. False — and nothing is recorded — when
    // the room is unknown or occupied, or the guest is already
    // checked in anywhere in the hotel.
    bool CheckIn(string guestName, string roomNumber);

    // Checks out whoever occupies the room. False when the room is
    // unknown or vacant.
    bool CheckOut(string roomNumber);

    // True while a guest occupies the room. Unknown room: false.
    bool IsOccupied(string roomNumber);
}
